/* 触屏没有真正的 hover：按下后 :hover 会一直粘住，把按钮留在悬浮态。 */
@media (hover: none) {
  .icon-btn:hover, .soft-btn:hover { background: #392753; transform: none; }
  .primary-btn:hover:not(:disabled) { background: #ffd45f; transform: none; }
}

/* 系统开启「增强对比度」时，把偏淡的边框和次要文字压深一档。 */
@media (prefers-contrast: more) {
  :root { --line: #9276b4; --muted: #efe4fb; }
  .stage-node { border-color: #a98cc8; }
  .game-info, .best-score, .empty-run { color: #f3e9ff; }
  .score-card, .target-card { border-color: #180d28; }
}

/* 系统开启「减少透明度」时，别再用毛玻璃。 */
@media (prefers-reduced-transparency: reduce) {
  dialog::backdrop { background: #190e37f2; backdrop-filter: none; }
  .site-header { background: #1c122f; }
}

/* 跳转链接：不聚焦时藏起来，Tab 到它才显示在页头之上。 */
.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  z-index: 20;
  padding: 10px 14px;
  border-radius: 10px;
  color: #2e1737;
  background: #ffd45f;
  font-size: 14px;
  font-weight: 850;
  text-decoration: none;
  transition: top .16s ease;
}
.skip-link:focus-visible { top: 12px; outline: 3px solid #ffdc81; outline-offset: 3px; }

test('the 96-pig wave cap fills exactly one wave at stage 8 and splits from stage 9 on', () => {
  const game = create();
  for (const stage of [7, 8, 9, 10, 11, 12]) {
    assert.equal(game.loadLevel(stage - 1), true, `stage ${stage}: load`);
    const state = game.getState();
    const targets = targetsAt(stage);
    const onField = targets < 96n ? targets : 96n;
    assert.equal(state.wave, 1n, `stage ${stage}: starts on wave 1`);
    assert.equal(BigInt(state.totalWaves), (targets + 95n) / 96n, `stage ${stage}: total waves`);
    assert.equal(BigInt(state.activeTargets), onField, `stage ${stage}: pigs on field`);
    assert.equal(BigInt(state.queuedTargets) + BigInt(state.activeTargets), targets, `stage ${stage}: bookkeeping`);
  }
  assert.equal(game.loadLevel(7), true);
  assert.equal(game.getState().totalWaves, 1n);
  assert.equal(game.getState().queuedTargets, 0n);
  assert.equal(game.loadLevel(8), true);
  assert.equal(game.getState().totalWaves, 2n);
  assert.equal(game.getState().queuedTargets, 96n);
});
